92|
93|  switch (parsedLanguageTag) {
94|    case `es-ES`:
95|      return euVatFormats.ES.test(vatNumber) || /^\d{9}$/.test(vatNumber);
96|    case `pt-PT`:
97|      return euVatFormats.PT.test(vatNumber) || /^\d{9}$/.test(vatNumber);
98|    case `de-AT`:
99|      return (
100|        /^ATU[0-9A-Z]{8}$/.test(vatNumber) ||
101|        /^[0-9A-Z]{2}-[0-9A-Z]{3}\/[0-9A-Z]{4}$/.test(vatNumber) ||
102|        euTaxFormats.DE.test(vatNumber)
103|      );
104|    case `nl-BE`:
105|    case `fr-BE`:
106|      return /^BE[0-9A-Z]{10}$/.test(vatNumber);
107|    case `de-CH`:
108|      // Switzerland DE format need a special check
109|      return (
110|        /^CHE[0-9A-Z]{9}$/.test(vatNumber) || /^[0-9A-Z]{6}$/.test(vatNumber)
111|      );
112|    case `it-CH`:
113|    case `fr-CH`:
114|      return /^CHE[0-9A-Z]{9}$/.test(vatNumber);
115|    case `it-IT`:
116|      return /^[0-9A-Z]{11}$/.test(vatNumber);
117|    case `fr-FR`:
118|      return /^FR[0-9A-Z]{11}$/.test(vatNumber);
119|    case `nl-NL`:
120|      return /^NL[0-9A-Z]{12}$/.test(vatNumber);
121|    case `sv-SE`:
122|      return /^SE[0-9A-Z]{10}01$/.test(vatNumber);
123|    case `de-DE`: {
124|      return euVatFormats.DE.test(vatNumber) || euTaxFormats.DE.test(vatNumber);
125|    }
126|    case `en-GB`:
127|      return (
128|        nonEuVatFormats.GB.test(vatNumber) || nonEuTaxFormats.GB.test(vatNumber)
129|      );
130|    default:
131|      return /^[A-Z0-9]{9}$/.test(vatNumber);
132|  }
133|};
